global.half=p=>({x:p[0]+p[1]+p[2],y:p[1]-p[0]+64});
global.buildGrid=async()=>{let m=await pal.readData('maps/'+pal.world.map+'.json');let c=new Int32Array(192*192).fill(-1),k=0;for(let y=0;y<192;y++)for(let x=0;x<192;x++){let a=y*192+x;if(c[a]>=0||m.rows[y]?.[x]!=='.')continue;let q=[a];c[a]=k;for(let i=0;i<q.length;i++){let a=q[i],x=a%192,y=Math.floor(a/192);for(let [u,v]of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]])if(u>=0&&u<192&&v>=0&&v<192&&m.rows[v]?.[u]==='.'&&c[v*192+u]<0){c[v*192+u]=k;q.push(v*192+u);}}k++;}global.grid={map:pal.world.map,c,m};return k;};
