global.walk=async(x,y)=>{for(let k=0;k<30;k++){await global.settle();if(pal.world.gx===x&&pal.world.gy===y)return true;let scene=pal.world.scene,p=await global.path(x,y);if(!p)return false;for(let s of p){await pal.step(s.dir,1);await global.settle();if(pal.world.scene!==scene)return false;if(pal.world.gx!==s.x||pal.world.gy!==s.y)break;}}return false;};

