global.walk2=async(x,y,max=1000)=>{if(global.grid?.map!==pal.world.map)await global.buildGrid();let rows=global.grid.m.rows.map(s=>s),map=pal.world.map,scene=pal.world.scene,blocked=global.runtimeBlocks[map]||new Set();global.runtimeBlocks[map]=blocked;for(let k=0;k<max;k++){await global.settle();if(pal.world.scene!==scene)return true;if(pal.world.gx===x&&pal.world.gy===y)return true;let oldRows=global.grid.m.rows;global.grid.m.rows=rows.map((s,y)=>Array.from(s).map((c,x)=>blocked.has(y*192+x)?'#':c).join(''));let path=await global.path(x,y);global.grid.m.rows=oldRows;if(!path)return false;for(let s of path){let r=await pal.step(s.dir,1);await pal.observe();await global.settle();if(pal.world.scene!==scene)return true;if(pal.world.gx!==s.x||pal.world.gy!==s.y){if(!r.ok&&r.reply?.reason==='blocked')blocked.add(s.y*192+s.x);else await pal.wait(100);break;}}}return false;};

