global.finalFight=async(limit=80)=>{let logs=[];for(let i=0;i<limit&&pal.world.battle;i++){if(pal.world.mode==='dialog'){await pal.advance(1);continue;}if(pal.world.mode!=='battle'){await pal.wait(100);continue;}let b=pal.world.battle,idx=b.turn.member,m=pal.world.members[idx],team=pal.world.members,has=id=>pal.world.items.some(x=>x.id===id&&x.amount>0),dead=team.findIndex(x=>x.hp<=0),un=team.findIndex(x=>x.hp>0&&!x.status?.includes('protect')),low=team.some(x=>x.hp>0&&x.hp<x.maxHp*.5),adds=b.enemies.filter(x=>x.hp>0&&x.name!=='拜月教主').length,r;if(has(141)&&low)r=await pal.battle('item',{item:141,target:idx});else if(dead>=0&&[98,96,95].some(has))r=await pal.battle('item',{item:[98,96,95].find(has),target:dead});else if(m.roleId===1){if(m.mp<65&&[110,111,109,108,107,106,104].some(has))r=await pal.battle('item',{item:[110,111,109,108,107,106,104].find(has),target:idx});else if(dead>=0)r=await pal.battle('magic',{magic:301,target:dead});else if(un===idx&&m.hp>m.maxHp*.75)r=await pal.battle('magic',{magic:309,target:idx});else r=await pal.battle('magic',{magic:300,target:0});}else if(m.roleId===4){if(dead>=0)r=await pal.battle('magic',{magic:302,target:dead});else r=await pal.battle('magic',{magic:394,target:1});}else{if(un>=0)r=await pal.battle('magic',{magic:310,target:un});else if(m.hp<400&&m.mp>=40)r=await pal.battle('magic',{magic:299,target:idx});else if(adds&&m.mp>250&&has(86))r=await pal.battle('magic',{magic:370,target:1});else if(!m.status?.includes('bravery')&&m.mp>=13)r=await pal.battle('magic',{magic:311,target:idx});else if(!m.status?.includes('dual-attack')&&m.mp>=22)r=await pal.battle('magic',{magic:390,target:idx});else r=await pal.battle('attack',{target:1});}logs.push(r.reply?.note);if(!r.ok&&pal.world.mode==='battle')await pal.battle('attack',{target:1});}global.finalCombatLog=(global.finalCombatLog||[]).concat(logs);return logs;};
